import{_ as d,o as e,c as o,ag as a}from"./chunks/framework.CrXGS008.js";const m=JSON.parse('{"title":"Definições","description":"","frontmatter":{},"headers":[],"relativePath":"pt/car-wash/settings.md","filePath":"pt/car-wash/settings.md"}'),s={name:"pt/car-wash/settings.md"};function r(i,t,c,n,l,p){return e(),o("div",null,[...t[0]||(t[0]=[a('<h1 id="definicoes" tabindex="-1">Definições <a class="header-anchor" href="#definicoes" aria-label="Permalink to &quot;Definições&quot;">​</a></h1><p>Todas as definições do Car Wash são editadas no <code>/nay</code>, na página <strong>Car Wash</strong> (âmbito <code>nay_car_wash.config</code>). As alterações são guardadas na base de dados e aplicadas de imediato a todos os jogadores. O <code>config.lua</code> contém valores iniciais opcionais: aplicam-se até uma definição ser alterada no <code>/nay</code>, e <strong>Repor</strong> volta a eles.</p><p>A coluna <strong>No /nay</strong> mostra o nome apresentado no painel. A chave é o nome usado pelo <code>config.lua</code> e pela <a href="/pt/nay-lib/api">API HTTP</a>.</p><h2 id="geral" tabindex="-1">Geral <a class="header-anchor" href="#geral" aria-label="Permalink to &quot;Geral&quot;">​</a></h2><table tabindex="0"><thead><tr><th>No /nay</th><th>Chave</th><th>Tipo</th><th>Predefinição</th><th>Descrição</th></tr></thead><tbody><tr><td>Ativado</td><td><code>Enabled</code></td><td>ligado / desligado</td><td>ligado</td><td>Ativa ou desativa todos os túneis e máquinas de alta pressão.</td></tr><tr><td>Interação a pé</td><td><code>InteractionMode</code></td><td><code>key</code> ou <code>target</code></td><td><code>key</code></td><td>Como os jogadores iniciam uma máquina de alta pressão: aviso de tecla (E) ou olho do target. Os túneis usam sempre a tecla E a partir do veículo.</td></tr><tr><td>Conta de pagamento</td><td><code>Account</code></td><td><code>cash</code>, <code>bank</code> ou <code>cash_then_bank</code></td><td><code>cash_then_bank</code></td><td>Onde o preço é cobrado. <code>cash_then_bank</code> recorre ao banco quando falta dinheiro.</td></tr><tr><td>Descontos por profissão</td><td><code>JobDiscounts</code></td><td>lista, até 32</td><td>nenhum</td><td>Descontos para uma profissão a partir de um grau, nos túneis e nas máquinas de alta pressão.</td></tr></tbody></table><p>Entradas de <strong>Descontos por profissão</strong>:</p><table tabindex="0"><thead><tr><th>No /nay</th><th>Chave</th><th>Tipo</th><th>Descrição</th></tr></thead><tbody><tr><td>Profissão</td><td><code>Job</code></td><td>texto, 1 a 32 caracteres</td><td>Nome da profissão, tal como no seu framework.</td></tr><tr><td>Grau mínimo</td><td><code>MinGrade</code></td><td>número, 0 a 100</td><td>Grau mais baixo que recebe o desconto.</td></tr><tr><td>Desconto (%)</td><td><code>Percent</code></td><td>número, 1 a 100</td><td>Desconto em percentagem. 100 torna a lavagem grátis.</td></tr></tbody></table><h2 id="tuneis" tabindex="-1">Túneis <a class="header-anchor" href="#tuneis" aria-label="Permalink to &quot;Túneis&quot;">​</a></h2><table tabindex="0"><thead><tr><th>No /nay</th><th>Chave</th><th>Tipo</th><th>Predefinição</th><th>Descrição</th></tr></thead><tbody><tr><td>Programas de lavagem</td><td><code>Programs</code></td><td>lista, 1 a 8</td><td>Express $150, Standard $250, Premium $400</td><td>Programas de lavagem oferecidos em todos os túneis.</td></tr><tr><td>Túneis</td><td><code>Tunnels</code></td><td>lista, até 32</td><td>Strawberry, Little Seoul</td><td>Os túneis. Posicionados com o <a href="/pt/car-wash/tunnels">editor de túneis</a>.</td></tr><tr><td>Largura máxima do veículo (m)</td><td><code>MaxVehicleWidth</code></td><td>metros, 1 a 6</td><td>2,25</td><td>Os veículos mais largos são recusados.</td></tr><tr><td>Classes de veículo bloqueadas</td><td><code>BlockedClasses</code></td><td>lista de classes de veículo</td><td>motas, bicicletas, barcos, helicópteros, aviões, comboios</td><td>Classes de veículo recusadas à entrada.</td></tr><tr><td>Recusar veículos limpos</td><td><code>RequireDirt</code></td><td>ligado / desligado</td><td>desligado</td><td>Recusa os veículos que já estão limpos.</td></tr><tr><td>Substituir os IPL das lavagens do mapa</td><td><code>ReplaceMapIpls</code></td><td>ligado / desligado</td><td>ligado</td><td>Em Strawberry, troca a lavagem original pela versão sem escovas. Desative se um mapa personalizado ou um gestor de mapping tratar dessa lavagem.</td></tr></tbody></table><p>Entradas de <strong>Programas de lavagem</strong>:</p><table tabindex="0"><thead><tr><th>No /nay</th><th>Chave</th><th>Tipo</th><th>Descrição</th></tr></thead><tbody><tr><td>Nome</td><td><code>Label</code></td><td>texto, 1 a 32 caracteres</td><td>Nome mostrado no menu de lavagem.</td></tr><tr><td>Preço</td><td><code>Price</code></td><td>número, 0 a 1000000</td><td>Preço antes dos descontos e da percentagem do túnel.</td></tr><tr><td>Velocidade (%)</td><td><code>SpeedPercent</code></td><td>número, 25 a 300</td><td>Velocidade relativa à velocidade do túnel.</td></tr><tr><td>Sabão</td><td><code>Soap</code></td><td>ligado / desligado</td><td>Aciona o arco de sabão.</td></tr><tr><td>Enxaguamento</td><td><code>Rinse</code></td><td>ligado / desligado</td><td>Aciona o arco de enxaguamento.</td></tr><tr><td>Secagem</td><td><code>Dry</code></td><td>ligado / desligado</td><td>Aciona o secador.</td></tr><tr><td>Cera (minutos)</td><td><code>WaxMinutes</code></td><td>número, 0 a 1440</td><td>Minutos durante os quais o veículo se mantém limpo depois da lavagem. 0 significa sem cera.</td></tr></tbody></table><p>As entradas de <strong>Túneis</strong> editam-se mais facilmente com o <a href="/pt/car-wash/tunnels">editor de túneis</a>, que preenche estes campos por si:</p><table tabindex="0"><thead><tr><th>No /nay</th><th>Chave</th><th>Tipo</th><th>Descrição</th></tr></thead><tbody><tr><td>Nome</td><td><code>Label</code></td><td>texto, até 48 caracteres</td><td>Título do menu de lavagem, também usado no histórico e nos webhooks. Opcional.</td></tr><tr><td>Aberto</td><td><code>Enabled</code></td><td>ligado / desligado</td><td>Fecha um túnel sem o eliminar.</td></tr><tr><td>Entrada</td><td><code>Entry</code></td><td>posição e direção</td><td>Onde o condutor para e prime E.</td></tr><tr><td>Início da linha</td><td><code>Start</code></td><td>posição</td><td>Início da linha que o veículo segue.</td></tr><tr><td>Fim da linha</td><td><code>Finish</code></td><td>posição</td><td>Fim da linha.</td></tr><tr><td>Largura (m)</td><td><code>Width</code></td><td>metros, 2 a 10</td><td>Largura da passagem: dimensiona os arcos, limita a largura do veículo (margem de 0,5 m) e é usada pela verificação de passagem bloqueada.</td></tr><tr><td>Velocidade (m/s)</td><td><code>Speed</code></td><td>metros por segundo, 0,5 a 8</td><td>Velocidade base dentro do túnel, multiplicada pela velocidade do programa.</td></tr><tr><td>Preço (%)</td><td><code>PricePercent</code></td><td>número, 0 a 1000</td><td>Percentagem aplicada a todos os preços de programa neste túnel. 100 mantém os preços.</td></tr><tr><td>Arco de sabão</td><td><code>SoapJet</code></td><td>posição</td><td>Arco de sabão.</td></tr><tr><td>Escova superior</td><td><code>HorizontalRoller</code></td><td>posição</td><td>Escova de cima.</td></tr><tr><td>Escovas laterais</td><td><code>VerticalRoller</code></td><td>posição</td><td>Escovas dos lados.</td></tr><tr><td>Arco de enxaguamento</td><td><code>RinseJet</code></td><td>posição</td><td>Arco de enxaguamento.</td></tr><tr><td>Secador</td><td><code>Dryer</code></td><td>posição</td><td>Secador a vapor. Opcional.</td></tr></tbody></table><p>As entradas de <strong>Classes de veículo bloqueadas</strong> têm um único campo, <strong>Classe</strong> (<code>Class</code>), escolhido pelo nome entre as classes de veículo do GTA.</p><h2 id="maquinas-de-alta-pressao" tabindex="-1">Máquinas de alta pressão <a class="header-anchor" href="#maquinas-de-alta-pressao" aria-label="Permalink to &quot;Máquinas de alta pressão&quot;">​</a></h2><table tabindex="0"><thead><tr><th>No /nay</th><th>Chave</th><th>Tipo</th><th>Predefinição</th><th>Descrição</th></tr></thead><tbody><tr><td>Máquinas de alta pressão</td><td><code>ManualEnabled</code></td><td>ligado / desligado</td><td>ligado</td><td>Ativa ou desativa as máquinas de alta pressão.</td></tr><tr><td>Props de máquina</td><td><code>ManualModels</code></td><td>lista, até 16</td><td><code>prop_gas_airunit01</code></td><td>Props do mundo que passam a ser máquinas de alta pressão, onde quer que o mapa os tenha.</td></tr><tr><td>Máquinas colocadas</td><td><code>ManualStations</code></td><td>lista, até 64</td><td>nenhuma</td><td>Máquinas de alta pressão posicionadas por si.</td></tr><tr><td>Preço por nível de sujidade</td><td><code>ManualPricePerLevel</code></td><td>número, 0 a 100000</td><td>15</td><td>Preço de um nível de sujidade, antes dos descontos por profissão.</td></tr><tr><td>Segundos por nível de sujidade</td><td><code>ManualSecondsPerLevel</code></td><td>segundos, 0,2 a 10</td><td>1</td><td>Tempo necessário para limpar um nível de sujidade.</td></tr></tbody></table><p>As entradas de <strong>Props de máquina</strong> têm um único campo, <strong>Nome do modelo</strong> (<code>Model</code>): o nome do modelo do prop (letras, números e underscores).</p><p>Entradas de <strong>Máquinas colocadas</strong>:</p><table tabindex="0"><thead><tr><th>No /nay</th><th>Chave</th><th>Tipo</th><th>Descrição</th></tr></thead><tbody><tr><td>Nome</td><td><code>Label</code></td><td>texto, até 48 caracteres</td><td>Nome da estação, usado no histórico e nos webhooks. Opcional.</td></tr><tr><td>Posição</td><td><code>Coords</code></td><td>posição e direção</td><td>Onde fica. <strong>Usar a minha posição</strong> preenche o campo com o sítio onde está.</td></tr></tbody></table><p>Mais detalhes na página <a href="/pt/car-wash/pressure-washers">Máquinas de alta pressão</a>.</p><h2 id="blips" tabindex="-1">Blips <a class="header-anchor" href="#blips" aria-label="Permalink to &quot;Blips&quot;">​</a></h2><table tabindex="0"><thead><tr><th>No /nay</th><th>Chave</th><th>Tipo</th><th>Predefinição</th><th>Descrição</th></tr></thead><tbody><tr><td>Mostrar blips</td><td><code>ShowBlips</code></td><td>ligado / desligado</td><td>ligado</td><td>Mostra no mapa os túneis e, enquanto as máquinas de alta pressão estiverem ativadas, as estações posicionadas.</td></tr><tr><td>Ícone do blip</td><td><code>BlipSprite</code></td><td>ícone de blip</td><td>100</td><td>Escolhido numa lista visual de ícones. Também é possível escrever qualquer número para um blip personalizado.</td></tr><tr><td>Cor do blip</td><td><code>BlipColor</code></td><td>cor de blip</td><td>63</td><td>Escolhida numa lista visual de cores.</td></tr><tr><td>Tamanho do blip</td><td><code>BlipScale</code></td><td>0,2 a 2</td><td>0,8</td><td>Tamanho do blip.</td></tr></tbody></table>',22)])])}const u=d(s,[["render",r]]);export{m as __pageData,u as default};
